/**
 * Engineering Action Summary and Recommended Next Action — 10 §14, §15.
 *
 * Every line is generated by a fixed rule from a number that is visible
 * elsewhere on this screen; no language model is involved (AC-10-18), and an
 * improvement Screen 08 did not calculate is never asserted (AC-10-19). The
 * panel says so in as many words, because a reader who cannot tell whether a
 * summary was computed or written has no way to check it.
 */

import { ArrowRight, ClipboardList, Lightbulb } from 'lucide-react';

import { Badge, Button } from '@/ui/primitives';
import { EngineeringInfo } from '@/ui/FieldLabel';
import type { RecommendedNextAction } from '@/thermal/overview/overviewTypes';

import { T10 } from './tooltips';

export function EngineeringActionSummary({
  lines,
  linesZh,
}: {
  lines: string[];
  linesZh: string[];
}) {
  return (
    <div className="flex flex-col gap-2">
      <ol className="flex flex-col gap-2">
        {lines.map((line, index) => (
          <li key={line} className="flex gap-2">
            <span className="mt-0.5 flex size-4 shrink-0 items-center justify-center rounded-full bg-accent-600 text-[9px] font-bold text-white tabular">
              {index + 1}
            </span>
            <span className="min-w-0 text-[11.5px] leading-relaxed text-ink-700">
              {line}
              <span className="block text-[10.5px] text-ink-500">{linesZh[index]}</span>
            </span>
          </li>
        ))}
      </ol>

      <p className="flex items-start gap-1.5 border-t border-line pt-2 text-[10px] leading-relaxed text-ink-400">
        <ClipboardList className="mt-0.5 size-3 shrink-0" aria-hidden />
        <span>
          Generated by fixed rules from the Screen 07/08/09 results above — no language model, and
          no improvement Screen 08 did not measure.
          <span className="block">
            由固定規則依上方 07/08/09 的結果產生；不使用語言模型，也不會列出 08 沒有實際量到的改善量。
          </span>
        </span>
      </p>
    </div>
  );
}

export function RecommendedNextActionPanel({
  recommended,
  onGoto,
}: {
  recommended: RecommendedNextAction;
  onGoto: (screenCode: string) => void;
}) {
  return (
    <div className="flex flex-col gap-2">
      <div className="flex flex-wrap items-center gap-2">
        <Lightbulb className="size-4 shrink-0 text-warn-600" aria-hidden />
        <span className="text-[13px] font-bold text-ink-900">{recommended.action}</span>
        <Badge tone="warn">{recommended.zh}</Badge>
        <EngineeringInfo zh={T10.recommendedNextAction} label="Recommended Next Action" />
      </div>

      <p className="text-[11.5px] leading-relaxed text-ink-700">
        {recommended.reason}
        <span className="block text-[10.5px] text-ink-500">{recommended.reason_zh}</span>
      </p>

      {recommended.goto && (
        <Button
          variant="primary"
          className="!h-8 self-start !text-[12px]"
          trailingIcon={<ArrowRight className="size-3.5" />}
          onClick={() => onGoto(recommended.goto as string)}
        >
          Go to Screen {recommended.goto} / 前往 {recommended.goto}
        </Button>
      )}
    </div>
  );
}
